// Sanitize and structure error diagnostics
const errorData = $json.execution || {};
const workflow = $json.workflow || {};

const workflowName = workflow.name || 'AI Graphic Design Studio';
const executionId = errorData.id || 'N/A';
const errorMsg = (errorData.error && errorData.error.message) || 'Unknown error occurred';
const failedNode = (errorData.lastNodeExecuted) || 'Unknown Node';
const timestamp = new Date().toISOString();

return [{
  json: {
    workflow_name: workflowName,
    execution_id: executionId,
    failed_node: failedNode,
    error_message: errorMsg,
    timestamp: timestamp,
    error_stack: (errorData.error && errorData.error.stack) || ''
  }
}];

